CREATE OR REPLACE FUNCTION public.calculate_booking_amounts()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Calculate num_nights
    NEW.num_nights := NEW.check_out_date - NEW.check_in_date;

    -- Calculate subtotal
    NEW.subtotal := NEW.price_per_night * NEW.num_nights * NEW.num_rooms;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_blog_slug(title text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    slug TEXT;
    counter INTEGER := 0;
    temp_slug TEXT;
BEGIN
    -- Convert to lowercase and replace spaces with hyphens
    slug := LOWER(TRIM(title));
    slug := REGEXP_REPLACE(slug, '[^a-z0-9\s-]', '', 'g');
    slug := REGEXP_REPLACE(slug, '\s+', '-', 'g');
    slug := REGEXP_REPLACE(slug, '-+', '-', 'g');

    -- Ensure slug is unique
    temp_slug := slug;
    WHILE EXISTS (SELECT 1 FROM blogs WHERE blogs.slug = temp_slug) LOOP
        counter := counter + 1;
        temp_slug := slug || '-' || counter;
    END LOOP;

    RETURN temp_slug;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_booking_reference()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    reference TEXT;
    exists BOOLEAN;
BEGIN
    LOOP
        -- Generate format: BK-YYYYMMDD-XXXX (e.g., BK-20250109-A7B2)
        reference := 'BK-' || TO_CHAR(NOW(), 'YYYYMMDD') || '-' ||
                     UPPER(SUBSTRING(MD5(RANDOM()::TEXT) FROM 1 FOR 4));

        -- Check if reference already exists
        SELECT EXISTS(SELECT 1 FROM public.bookings WHERE booking_reference = reference) INTO exists;

        -- Exit loop if reference is unique
        EXIT WHEN NOT exists;
    END LOOP;

    RETURN reference;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$
